 void retentionMenu(){String[] labels={"Отключено","Старше 7 дней","Старше 14 дней","Старше 30 дней","Старше 60 дней","Старше 90 дней"};int[] days={0,7,14,30,60,90};int selected=0;for(int i=0;i<days.length;i++)if(days[i]==prefs.getInt("recordRetentionDays",0))selected=i;new AlertDialog.Builder(this).setTitle("Автоудаление записей").setSingleChoiceItems(labels,selected,(d,i)->{d.dismiss();if(i==0){prefs.edit().putInt("recordRetentionDays",0).apply();return;}new AlertDialog.Builder(this).setTitle("Включить автоудаление?").setMessage("Перед новой записью будут удаляться локальные записи старше "+days[i]+" дней, кроме защищённых. Файлы на USB и NAS не затрагиваются.").setPositiveButton("Включить",(x,w)->prefs.edit().putInt("recordRetentionDays",days[i]).apply()).setNegativeButton("Отмена",null).show();}).setNegativeButton("Закрыть",null).show();}
 void directRecordingMenu(){boolean enabled=prefs.getBoolean("recordDirect",false);new AlertDialog.Builder(this).setTitle("Прямая запись • "+(enabled?"включена":"выключена")).setMessage("При выбранной папке USB или NAS запись идёт сразу туда, без полной локальной копии. При отключении накопителя возможна частичная запись. Лимит и автоудаление локальных записей не применяются. Для HLS требуется временное место для сегмента.").setPositiveButton("Включить",(d,w)->{if(prefs.getString("recordTree","").isEmpty()&&prefs.getString("recordNas","").isEmpty()){recordStorageMenu();return;}prefs.edit().putBoolean("recordDirect",true).apply();}).setNeutralButton("Выключить",(d,w)->prefs.edit().putBoolean("recordDirect",false).apply()).setNegativeButton("Закрыть",null).show();}
 void recordStorageMenu(){String tree=prefs.getString("recordTree",""),nas=prefs.getString("recordNas","");String currentDestination=!tree.isEmpty()?"Папка USB / накопителя":!nas.isEmpty()?"SMB / NAS":"Внутренняя память";new AlertDialog.Builder(this).setTitle("Хранение записей • "+currentDestination).setItems(new String[]{"Только внутренняя память","Автокопирование на USB / накопитель","Автокопирование на NAS (гостевой доступ)"},(d,i)->{if(i==0){prefs.edit().remove("recordTree").remove("recordNas").remove("recordNasId").apply();}else if(i==1){android.content.Intent intent=new android.content.Intent(android.content.Intent.ACTION_OPEN_DOCUMENT_TREE);intent.addFlags(android.content.Intent.FLAG_GRANT_READ_URI_PERMISSION|android.content.Intent.FLAG_GRANT_WRITE_URI_PERMISSION|android.content.Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);try{startActivityForResult(intent,603);}catch(Exception e){Toast.makeText(this,"Выбор папки недоступен на этой приставке",Toast.LENGTH_LONG).show();}}else{EditText e=new EditText(this);e.setSingleLine(true);e.setHint("smb://192.168.1.10/Video/");e.setText(nas);new AlertDialog.Builder(this).setTitle("Папка NAS").setMessage("Только папка с гостевым доступом. Оригинал остаётся во внутренней памяти.").setView(e).setPositiveButton("Сохранить",(x,w)->{String u=e.getText().toString().trim();android.net.Uri parsed=android.net.Uri.parse(u);if(!"smb".equals(parsed.getScheme())||parsed.getHost()==null||u.contains("@")||parsed.getPath()==null||parsed.getPath().length()<2||parsed.getQuery()!=null||parsed.getFragment()!=null){Toast.makeText(this,"Некорректный SMB адрес",Toast.LENGTH_SHORT).show();return;}prefs.edit().putString("recordNas",u.endsWith("/")?u:u+"/").remove("recordNasId").remove("recordTree").apply();}).setNegativeButton("Отмена",null).show();}}).show();}
