 void applyScreenPolicy(){if(prefs.getBoolean("keepScreenAwake",true))getWindow().addFlags(android.view.WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);else getWindow().clearFlags(android.view.WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);}
 boolean resumeLiveAfterSleep=false,powerRegistered=false;
 boolean interactive(){android.os.PowerManager pm=(android.os.PowerManager)getSystemService(POWER_SERVICE);return pm==null||pm.isInteractive();}
 void pauseForSleep(){if(player==null||!prefs.getBoolean("resumeAfterSleep",true))return;if(current!=null&&!isArchive()&&player.getPlayWhenReady())resumeLiveAfterSleep=true;player.pause();}
 void resumeAfterSleep(){if(!resumeLiveAfterSleep||!activityVisible||!interactive()||player==null)return;resumeLiveAfterSleep=false;if(!prefs.getBoolean("resumeAfterSleep",true)||current==null||isArchive()||locked(current.group))return;if(player.getPlaybackState()==androidx.media3.common.Player.STATE_IDLE)player.prepare();player.play();}
 final android.content.BroadcastReceiver screenEvents=new android.content.BroadcastReceiver(){@Override public void onReceive(android.content.Context context,android.content.Intent intent){if(android.content.Intent.ACTION_SCREEN_OFF.equals(intent.getAction())){if(activityVisible)pauseForSleep();}else if(android.content.Intent.ACTION_SCREEN_ON.equals(intent.getAction()))resumeAfterSleep();}};
 void registerScreenEvents(){if(powerRegistered)return;android.content.IntentFilter filter=new android.content.IntentFilter(android.content.Intent.ACTION_SCREEN_OFF);filter.addAction(android.content.Intent.ACTION_SCREEN_ON);if(android.os.Build.VERSION.SDK_INT>=33)registerReceiver(screenEvents,filter,android.content.Context.RECEIVER_NOT_EXPORTED);else registerReceiver(screenEvents,filter);powerRegistered=true;}
 void cacheMenu(){File[] files=getCacheDir().listFiles((dir,name)->name.startsWith("epg_")&&name.endsWith(".bin"));long bytes=0;if(files!=null)for(File file:files)bytes+=file.length();new AlertDialog.Builder(this).setTitle("Кеш телепрограммы").setMessage(String.format(Locale.US,"На диске: %.1f МБ\nЗаписи, плейлисты и настройки не удаляются.",bytes/1048576.0)).setPositiveButton("Очистить",(d,w)->{long removed=0;if(files!=null)for(File file:files){long length=file.length();if(file.delete())removed+=length;}Toast.makeText(this,String.format(Locale.US,"Удалено %.1f МБ",removed/1048576.0),Toast.LENGTH_SHORT).show();}).setNegativeButton("Закрыть",null).show();}
