 void opacityMenu(){String[] names={"Главное и быстрое меню","Плитки меню","Список каналов","Информационная панель","Сбросить"};String[] keys={"menuOpacity","tileOpacity","sidebarOpacity","infoOpacity"};new AlertDialog.Builder(this).setTitle("Прозрачность интерфейса").setItems(names,(d,i)->{if(i==4){android.content.SharedPreferences.Editor edit=prefs.edit();for(String key:keys)edit.remove(key);edit.apply();applyOverlayOpacity();return;}String[] labels={"0% — непрозрачный","10%","15% — стандарт","20%","30%","40%","50%"};int[] values={100,90,85,80,70,60,50};int selected=2;for(int j=0;j<values.length;j++)if(values[j]==prefs.getInt(keys[i],85))selected=j;new AlertDialog.Builder(this).setTitle(names[i]).setSingleChoiceItems(labels,selected,(x,j)->{prefs.edit().putInt(keys[i],values[j]).apply();applyOverlayOpacity();x.dismiss();}).setNegativeButton("Отмена",null).show();}).setNegativeButton("Закрыть",null).show();}
