 String attribute(String line,String key){java.util.regex.Matcher m=java.util.regex.Pattern.compile("(?:^|\\s)"+java.util.regex.Pattern.quote(key)+"=\"([^\"]*)\"").matcher(line);return m.find()?m.group(1):"";}
 void archive(Channel ch,Epg.Programme p){if(locked(ch.group)){askPin(()->archiveAllowed(ch,p));return;}archiveAllowed(ch,p);} void archiveAllowed(Channel ch,Epg.Programme p){long now=System.currentTimeMillis();if(p.start>=now||ch.catchupDays<=0||now-p.start>ch.catchupDays*86400000L){Toast.makeText(this,"Архив недоступен для этой передачи",Toast.LENGTH_LONG).show();return;}String template=ch.catchupSource.isEmpty()?prefs.getString("archiveTemplate_"+prefs.getString("activeSource",""),""):ch.catchupSource;if(template.isEmpty()){archiveSettings();return;}String u=template.replace("{url}",ch.url).replace("{utc}",Long.toString(p.start/1000)).replace("{utcend}",Long.toString(p.end/1000)).replace("{duration}",Long.toString((p.end-p.start)/1000)).replace("{lutc}",Long.toString(now/1000)).replace("{start}",Long.toString(p.start/1000)).replace("{end}",Long.toString(p.end/1000));if(!ch.catchupSource.isEmpty()&&ch.catchup.equals("append"))u=ch.url+u;if(!u.startsWith("http://")&&!u.startsWith("https://")||u.contains("{")){Toast.makeText(this,"Неподдерживаемый формат архива",Toast.LENGTH_LONG).show();return;}closeShift();current=ch;applyAudioTrim();status.setText("Архив • "+p.title);player.setMediaItem(MediaItem.fromUri(u));player.prepare();player.play();}
 void archiveSettings(){String key="archiveTemplate_"+prefs.getString("activeSource","");EditText input=new EditText(this);input.setText(prefs.getString(key,""));input.setHint("{url}&start={utc}&end={utcend}");new AlertDialog.Builder(this).setTitle("Формат архивной ссылки").setMessage("Введите шаблон, предоставленный оператором IPTV. {url} — исходный поток; {utc}, {utcend} — начало и конец в секундах Unix; {duration} — длительность. Пример в поле не является подтверждённым форматом вашего оператора.").setView(input).setPositiveButton("Сохранить",(d,w)->prefs.edit().putString(key,input.getText().toString().trim()).apply()).setNegativeButton("Отмена",null).show();}
 void parse(String data){channels.clear();String name="",g="",id="",logo="",catchup="",source="";boolean declaredUhd=false;int days=0;for(String raw:data.split("\\r?\\n")){String l=raw.trim();if(l.startsWith("#EXTINF")){int comma=l.indexOf(',');name=comma>=0?l.substring(comma+1):"Канал";java.util.regex.Matcher m=java.util.regex.Pattern.compile("group-title=\"([^\"]*)\"").matcher(l);g=m.find()?m.group(1):"Без группы";java.util.regex.Matcher t=java.util.regex.Pattern.compile("tvg-id=\"([^\"]*)\"").matcher(l);id=t.find()?t.group(1):"";logo=attribute(l,"tvg-logo");declaredUhd=uhdLabel(attribute(l,"tvg-name")+" "+attribute(l,"resolution")+" "+attribute(l,"quality"));catchup=attribute(l,"catchup");source=attribute(l,"catchup-source");try{String retention=attribute(l,"catchup-days");if(retention.isEmpty())retention=attribute(l,"tvg-rec");days=Integer.parseInt(retention);}catch(Exception e){days=0;}}else if(l.startsWith("#EXTGRP:")){g=l.substring(8).trim();}else if(l.startsWith("http://")||l.startsWith("https://")){Channel ch=new Channel(name.isEmpty()?l:name,l,g);ch.id=id;ch.detectedUhd=declaredUhd;declaredUhd=false;ch.logo=logo;logo="";ch.catchup=catchup;ch.catchupSource=source;ch.catchupDays=days;channels.add(ch);catchup="";source="";days=0;id="";name="";g="";}}}
 static final java.util.regex.Pattern UHD_PATTERN=java.util.regex.Pattern.compile("(?iu)(?<![\\p{L}\\p{N}])(?:4k|4к|uhd|2160p|2160|ultra[ -]?hd)(?![\\p{L}\\p{N}])");static boolean uhdLabel(String label){return UHD_PATTERN.matcher(label).find();}
