 void play(Channel c){if(locked(c.group)){askPin(()->playAllowed(c));return;}playAllowed(c);} void playAllowed(Channel c){if(localShift!=null){closeShift();player.stop();}if(current==c&&!isArchive()&&player.getPlayerError()==null&&player.getPlaybackState()!=androidx.media3.common.Player.STATE_IDLE&&player.getPlaybackState()!=androidx.media3.common.Player.STATE_ENDED){player.play();video.requestFocus();showChannelInfo();return;}current=c;refreshChannelRows();usingBackup=false;player.setPlaybackSpeed(1f);applyAudioTrim();remember(c);Epg.Programme p=epg.current(c.id);status.setText(c.name+(p==null?"":" • "+p.title));player.setMediaItem(liveItem(c));player.prepare();player.play();video.requestFocus();showChannelInfo();}
 final Handler retryHandler=new Handler(Looper.getMainLooper());int retryCount=0;boolean activityVisible=false;
