 void recoverPlayback(androidx.media3.common.PlaybackException error){if(localShift!=null){returnLive();Toast.makeText(this,"Локальный буфер недоступен",Toast.LENGTH_SHORT).show();return;}retryHandler.removeCallbacksAndMessages(null);int code=error.errorCode;boolean transientError=code==2001||code==2002||code==2000||code==1002;if(activityVisible&&player.getPlayWhenReady()&&prefs.getBoolean("autoReconnect",true)&&((transientError&&retryCount>=4)||code==2004||code==2005)&&switchBackup())return;MediaItem item=player.getCurrentMediaItem();if(!activityVisible||!player.getPlayWhenReady()||!prefs.getBoolean("autoReconnect",true)||!transientError||item==null||retryCount>=4){status.setText("Ошибка воспроизведения: "+error.getErrorCodeName());return;}int attempt=++retryCount;long delay=new long[]{1000,2000,4000,8000}[attempt-1];status.setText("Восстановление соединения "+attempt+"/4…");retryHandler.postDelayed(()->{if(!activityVisible||isDestroyed()||player.getCurrentMediaItem()!=item||!player.getPlayWhenReady())return;player.prepare();player.play();},delay);}
 void playbackSettings(){String[] labels={"Аудиодорожка","Субтитры","Масштаб изображения","Скорость воспроизведения","Внешний плеер","Диагностика потока","Выравнивание громкости","Резервный источник"};new AlertDialog.Builder(this).setTitle("Воспроизведение").setItems(labels,(d,i)->{if(i==0)tracks(androidx.media3.common.C.TRACK_TYPE_AUDIO);else if(i==1)tracks(androidx.media3.common.C.TRACK_TYPE_TEXT);else if(i==2)new AlertDialog.Builder(this).setItems(new String[]{"По размеру","Заполнить","Увеличить"},(x,j)->video.setResizeMode(new int[]{0,3,4}[j])).show();else if(i==3)new AlertDialog.Builder(this).setItems(new String[]{"0.75x","1x","1.25x","1.5x","2x"},(x,j)->player.setPlaybackSpeed(new float[]{.75f,1f,1.25f,1.5f,2f}[j])).show();else if(i==5)streamInfo();else if(i==6)audioLevelMenu();else if(i==7)backupStreamMenu();else if(current!=null){try{android.content.Intent intent=new android.content.Intent(android.content.Intent.ACTION_VIEW);intent.setDataAndType(android.net.Uri.parse(current.url),"video/*");startActivity(android.content.Intent.createChooser(intent,"Внешний плеер"));}catch(Exception e){Toast.makeText(this,"Нет внешнего плеера",Toast.LENGTH_SHORT).show();}}}).show();}
