 void equalizerMenu(){String[] names={"Низкие частоты","Средние частоты","Высокие частоты","Пресеты"};new AlertDialog.Builder(this).setTitle("Эквалайзер").setItems(names,(d,i)->{if(i==3){String[] presets={"Ровный","Кино","Речь","Музыка","Мягкий звук"};int[][] gains={{0,0,0},{3,1,2},{-3,4,1},{3,-1,3},{-2,0,-3}};new AlertDialog.Builder(this).setTitle("Пресеты").setItems(presets,(x,j)->{prefs.edit().putInt("eqBass",gains[j][0]).putInt("eqMid",gains[j][1]).putInt("eqTreble",gains[j][2]).apply();applySoundProfile();}).show();return;}String key=new String[]{"eqBass","eqMid","eqTreble"}[i];String[] levels={"−6 дБ","−3 дБ","0 дБ","+3 дБ","+6 дБ"};new AlertDialog.Builder(this).setTitle(names[i]).setSingleChoiceItems(levels,Math.max(0,Math.min(4,(prefs.getInt(key,0)+6)/3)),(x,j)->{prefs.edit().putInt(key,-6+j*3).apply();applySoundProfile();x.dismiss();}).show();}).show();}
 void balanceMenu(){String[] labels={"Только левый","Левый +","По центру","Правый +","Только правый"};new AlertDialog.Builder(this).setTitle("Баланс стерео").setSingleChoiceItems(labels,Math.max(0,Math.min(4,(prefs.getInt("audioBalance",0)+100)/50)),(d,i)->{prefs.edit().putInt("audioBalance",-100+i*50).apply();applySoundProfile();d.dismiss();}).show();}
 void tracks(int type){ArrayList<String> labels=new ArrayList<>();ArrayList<androidx.media3.common.TrackSelectionOverride> overrides=new ArrayList<>();labels.add("Автоматически");overrides.add(null);if(type==androidx.media3.common.C.TRACK_TYPE_TEXT){labels.add("Отключить");overrides.add(null);}for(androidx.media3.common.Tracks.Group g:player.getCurrentTracks().getGroups()){if(g.getType()!=type)continue;for(int i=0;i<g.length;i++){if(!g.isTrackSupported(i))continue;androidx.media3.common.Format f=g.getTrackFormat(i);labels.add((f.label==null?"Дорожка "+(i+1):f.label)+(f.language==null?"":" • "+f.language));overrides.add(new androidx.media3.common.TrackSelectionOverride(g.getMediaTrackGroup(),i));}}new AlertDialog.Builder(this).setItems(labels.toArray(new String[0]),(d,i)->{androidx.media3.common.TrackSelectionParameters.Builder b=player.getTrackSelectionParameters().buildUpon().clearOverridesOfType(type).setTrackTypeDisabled(type,type==androidx.media3.common.C.TRACK_TYPE_TEXT&&i==1);if(overrides.get(i)!=null)b.addOverride(overrides.get(i));player.setTrackSelectionParameters(b.build());}).show();}
 void multiView(){if(lightMode()){Toast.makeText(this,"Мультиэкран отключён в экономном режиме. Выберите полный режим в настройках.",Toast.LENGTH_LONG).show();return;}if(displayed.size()<2){Toast.makeText(this,"Нужно минимум два канала",Toast.LENGTH_SHORT).show();return;}String[] names=new String[displayed.size()];boolean[] checked=new boolean[names.length];ArrayList<Channel> options=new ArrayList<>(displayed);for(int i=0;i<names.length;i++)names[i]=options.get(i).name;new AlertDialog.Builder(this).setTitle("Выберите 2–4 канала").setMultiChoiceItems(names,checked,(d,i,b)->checked[i]=b).setPositiveButton("Открыть",(d,w)->{ArrayList<Channel> selected=new ArrayList<>();for(int i=0;i<checked.length;i++)if(checked[i])selected.add(options.get(i));if(selected.size()<2||selected.size()>4){Toast.makeText(this,"Выберите от двух до четырёх каналов",Toast.LENGTH_SHORT).show();return;}showMulti(selected);}).setNegativeButton("Отмена",null).show();}
 void showMulti(ArrayList<Channel> selected){for(Channel ch:selected)if(locked(ch.group)){askPin(()->showMultiAllowed(selected));return;}showMultiAllowed(selected);} void showMultiAllowed(ArrayList<Channel> selected){boolean resume=player.isPlaying();player.pause();ArrayList<ExoPlayer> players=new ArrayList<>();LinearLayout panel=new LinearLayout(this);panel.setOrientation(1);Dialog dialog=new Dialog(this,android.R.style.Theme_Material_NoActionBar);dialog.setContentView(panel);dialog.setOnDismissListener(d->{for(ExoPlayer p:players)p.release();if(resume&&!isFinishing())player.play();});for(int i=0;i<selected.size();i+=2){LinearLayout row=new LinearLayout(this);panel.addView(row,new LinearLayout.LayoutParams(-1,0,1));for(int j=i;j<Math.min(i+2,selected.size());j++){Channel ch=selected.get(j);LinearLayout tile=new LinearLayout(this);tile.setOrientation(1);row.addView(tile,new LinearLayout.LayoutParams(0,-1,1));ExoPlayer p=new ExoPlayer.Builder(this).setLoadControl(new androidx.media3.exoplayer.DefaultLoadControl.Builder().setBufferDurationsMs(5000,12000,1000,2000).setTargetBufferBytes(12*1024*1024).setPrioritizeTimeOverSizeThresholds(false).build()).build();players.add(p);PlayerView pv=new PlayerView(this);pv.setUseController(false);pv.setPlayer(p);tile.addView(pv,new LinearLayout.LayoutParams(-1,0,1));Button audio=new Button(this);audio.setText(ch.name+" • Звук");tile.addView(audio);audio.setOnClickListener(v->{for(ExoPlayer other:players)other.setVolume(other==p?1f:0f);});p.setVolume(j==0?1f:0f);p.setMediaItem(MediaItem.fromUri(ch.url));p.prepare();p.play();}}Button close=new Button(this);close.setText("Закрыть мультиэкран");close.setOnClickListener(v->dialog.dismiss());panel.addView(close);dialog.show();dialog.getWindow().setLayout(-1,-1);}
 File recordingDir(){File dir=new File(getFilesDir(),"recordings");dir.mkdirs();return dir;}
 void recordingCommand(String action,String url,String title){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED&&!prefs.getBoolean("recordNotificationAsked",false)){prefs.edit().putBoolean("recordNotificationAsked",true).apply();requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},812);}android.content.Intent intent=new android.content.Intent(this,RecordingService.class).setAction(action);if(url!=null)intent.putExtra("url",url);if(title!=null)intent.putExtra("title",title);try{if(android.os.Build.VERSION.SDK_INT>=26)startForegroundService(intent);else startService(intent);}catch(Exception e){Toast.makeText(this,"Не удалось запустить службу записи",Toast.LENGTH_LONG).show();}}
 void record(){if(RecordingService.active){recordingCommand("stop",null,null);status.setText("Остановка записи…");return;}if(current==null){Toast.makeText(this,"Выберите канал",Toast.LENGTH_SHORT).show();return;}if(locked(current.group)){Channel ch=current;askPin(()->recordingCommand("record",ch.url,ch.name));return;}recordingCommand("record",activeLiveUrl(current),current.name);status.setText("Запуск записи • "+current.name);}
 boolean protectedRecording(File f){return prefs.getStringSet("protectedRecordings",Collections.emptySet()).contains(f.getName());}
 void toggleRecordingProtection(File f){synchronized(RecordingService.class){Set<String> names=new HashSet<>(prefs.getStringSet("protectedRecordings",Collections.emptySet()));if(!names.remove(f.getName()))names.add(f.getName());prefs.edit().putStringSet("protectedRecordings",names).apply();}}
 void recordings(){File[] files=recordingDir().listFiles((dir,name)->name.endsWith(".ts"));if(files==null||files.length==0){Toast.makeText(this,"Нет записей",Toast.LENGTH_SHORT).show();return;}Arrays.sort(files,(a,b)->Long.compare(b.lastModified(),a.lastModified()));String[] labels=new String[files.length];for(int i=0;i<files.length;i++)labels[i]=(protectedRecording(files[i])?"🔒 ":"")+files[i].getName()+" • "+files[i].length()/1048576+" МБ";new AlertDialog.Builder(this).setTitle("Мои записи").setItems(labels,(d,i)->new AlertDialog.Builder(this).setItems(new String[]{"Воспроизвести","Удалить","Экспорт на накопитель","Экспорт в SMB / NAS",protectedRecording(files[i])?"Снять защиту":"Защитить от удаления"},(x,j)->{if(RecordingService.active){Toast.makeText(this,"Сначала остановите запись",Toast.LENGTH_SHORT).show();return;}if(j==4){toggleRecordingProtection(files[i]);recordings();return;}if(j==1&&protectedRecording(files[i])){Toast.makeText(this,"Сначала снимите защиту записи",Toast.LENGTH_LONG).show();return;}if(j==3){smbDialog(files[i]);return;}if(j==2){chooseExport(files[i]);return;}if(j==0){current=null;applyAudioTrim();player.setMediaItem(MediaItem.fromUri(android.net.Uri.fromFile(files[i])));player.prepare();player.play();status.setText("Запись • "+labels[i]);}else new AlertDialog.Builder(this).setMessage("Удалить запись?").setPositiveButton("Удалить",(q,z)->{if(!protectedRecording(files[i])&&!RecordingService.active)files[i].delete();recordings();}).setNegativeButton("Отмена",null).show();}).show()).show();}
 File pendingExport;
 void localVideo(){android.content.Intent i=new android.content.Intent(android.content.Intent.ACTION_OPEN_DOCUMENT);i.addCategory(android.content.Intent.CATEGORY_OPENABLE);i.setType("video/*");try{startActivityForResult(i,601);}catch(android.content.ActivityNotFoundException e){Toast.makeText(this,"Файловый менеджер недоступен",Toast.LENGTH_LONG).show();}}
 void chooseExport(File file){pendingExport=file;android.content.Intent i=new android.content.Intent(android.content.Intent.ACTION_CREATE_DOCUMENT);i.addCategory(android.content.Intent.CATEGORY_OPENABLE);i.setType("video/mp2t");i.putExtra(android.content.Intent.EXTRA_TITLE,file.getName());try{startActivityForResult(i,602);}catch(Exception e){pendingExport=null;Toast.makeText(this,"Файловый менеджер недоступен",Toast.LENGTH_LONG).show();}}
 void exportRecording(android.net.Uri uri){File source=pendingExport;pendingExport=null;if(source==null||!source.isFile())return;status.setText("Копирование записи…");new Thread(()->{try(InputStream in=new FileInputStream(source);OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException();byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)out.write(b,0,n);out.flush();runOnUiThread(()->status.setText("Запись экспортирована"));}catch(Exception e){runOnUiThread(()->status.setText("Ошибка экспорта записи"));}}).start();}
 org.json.JSONArray nasFolders(){try{return new org.json.JSONArray(prefs.getString("nasFolders","[]"));}catch(Exception e){return new org.json.JSONArray();}}
 void nasFavorites(){org.json.JSONArray a=nasFolders();String[] labels=new String[a.length()+1];labels[0]="+ Добавить сетевую папку";for(int i=0;i<a.length();i++)labels[i+1]=a.optJSONObject(i).optString("name");new AlertDialog.Builder(this).setTitle("Избранные сетевые папки").setItems(labels,(d,i)->{if(i==0){addNasFolder();return;}org.json.JSONObject o=a.optJSONObject(i-1);if(o==null)return;String id=o.optString("id"),url=o.optString("url");new AlertDialog.Builder(this).setTitle(o.optString("name")).setItems(new String[]{"Открыть","Использовать для записи","Удалить из избранного"},(x,j)->{if(j==2){org.json.JSONArray latest=nasFolders();for(int k=latest.length()-1;k>=0;k--)if(id.equals(latest.optJSONObject(k).optString("id")))latest.remove(k);prefs.edit().putString("nasFolders",latest.toString()).apply();NasSecrets.remove(this,id);if(id.equals(prefs.getString("recordNasId","")))prefs.edit().remove("recordNasId").remove("recordNas").apply();nasFavorites();return;}try{String[] auth=NasSecrets.read(this,id);if(j==0)browseSmb(url,auth[0],auth[1],new ArrayList<String>());else{prefs.edit().putString("recordNas",url).putString("recordNasId",id).remove("recordTree").apply();Toast.makeText(this,"NAS выбран для записи",Toast.LENGTH_SHORT).show();}}catch(Exception e){Toast.makeText(this,"Учётные данные недоступны. Добавьте папку заново.",Toast.LENGTH_LONG).show();}}).show();}).setNegativeButton("Закрыть",null).show();}
 void addNasFolder(){LinearLayout fields=new LinearLayout(this);fields.setOrientation(1);EditText name=new EditText(this),address=new EditText(this),user=new EditText(this),password=new EditText(this);name.setHint("Название папки");address.setHint("smb://192.168.1.10/Video/");user.setHint("Логин (пусто — гость)");password.setHint("Пароль");password.setInputType(129);for(EditText e:new EditText[]{name,address,user,password}){e.setSingleLine(true);fields.addView(e);}new AlertDialog.Builder(this).setTitle("Добавить сетевую папку").setView(fields).setPositiveButton("Сохранить",(d,w)->{String url=address.getText().toString().trim();android.net.Uri parsed=android.net.Uri.parse(url);if(!"smb".equals(parsed.getScheme())||parsed.getHost()==null||url.contains("@")||parsed.getQuery()!=null||parsed.getFragment()!=null||parsed.getPath()==null||parsed.getPath().length()<2){Toast.makeText(this,"Некорректный SMB адрес",Toast.LENGTH_LONG).show();return;}String id=UUID.randomUUID().toString();try{NasSecrets.save(this,id,user.getText().toString(),password.getText().toString());org.json.JSONArray a=nasFolders();org.json.JSONObject o=new org.json.JSONObject();o.put("id",id);o.put("name",name.getText().toString().trim().isEmpty()?url:name.getText().toString().trim());o.put("url",url.endsWith("/")?url:url+"/");a.put(o);if(!prefs.edit().putString("nasFolders",a.toString()).commit())throw new IOException();nasFavorites();}catch(Exception e){NasSecrets.remove(this,id);Toast.makeText(this,"Не удалось безопасно сохранить данные",Toast.LENGTH_LONG).show();}}).setNegativeButton("Отмена",null).show();}
 void smbDialog(File source){LinearLayout fields=new LinearLayout(this);fields.setOrientation(1);EditText address=new EditText(this),user=new EditText(this),password=new EditText(this);address.setHint(source==null?"smb://192.168.1.10/Video/":"smb://192.168.1.10/Video/file.ts");if(source==null)address.setText(prefs.getString("lastSmbFolder",""));user.setHint("Пользователь (пусто — гость)");password.setHint("Пароль");password.setInputType(129);for(EditText e:new EditText[]{address,user,password}){e.setSingleLine();fields.addView(e);}new AlertDialog.Builder(this).setTitle(source==null?"Видео с SMB / NAS":"Экспорт записи в SMB").setView(fields).setPositiveButton(source==null?"Открыть":"Копировать",(d,w)->{String url=address.getText().toString().trim(),login=user.getText().toString(),secret=password.getText().toString();if(!url.startsWith("smb://")||url.contains("@")){status.setText("Введите SMB-адрес без логина и пароля");return;}if(source==null){if(url.endsWith("/"))browseSmb(url,login,secret,new ArrayList<String>());else playSmb(url,login,secret);return;}status.setText("Передача файла SMB…");new Thread(()->{try{SmbStorage.upload(url,login,secret,source);runOnUiThread(()->status.setText("Запись экспортирована в SMB"));}catch(Exception e){runOnUiThread(()->status.setText("Ошибка SMB: проверьте адрес, доступ и размер файла"));}}).start();}).setNegativeButton("Отмена",null).show();}
 int smbBrowseGeneration=0;
 void browseSmb(String url,String login,String password,ArrayList<String> parents){int generation=++smbBrowseGeneration;status.setText("Чтение папки SMB…");android.app.ProgressDialog progress=new android.app.ProgressDialog(this);progress.setMessage("Чтение сетевой папки…");progress.setCancelable(true);progress.setOnCancelListener(d->{if(generation==smbBrowseGeneration)smbBrowseGeneration++;});progress.show();new Thread(()->{try{java.util.List<SmbStorage.Entry> entries=SmbStorage.list(url,login,password);runOnUiThread(()->{if(isDestroyed()||generation!=smbBrowseGeneration)return;progress.dismiss();prefs.edit().putString("lastSmbFolder",url).apply();status.setText("Сетевая папка • "+entries.size()+" элементов");String[] names=new String[entries.size()];for(int i=0;i<names.length;i++){SmbStorage.Entry e=entries.get(i);names[i]=(e.directory?"📁 ":"▶ ")+e.name;}AlertDialog.Builder dialog=new AlertDialog.Builder(this).setTitle("SMB • "+android.net.Uri.parse(url).getLastPathSegment()).setItems(names,(d,i)->{SmbStorage.Entry e=entries.get(i);if(e.directory){ArrayList<String> next=new ArrayList<>(parents);next.add(url);browseSmb(e.address.endsWith("/")?e.address:e.address+"/",login,password,next);}else playSmb(e.address,login,password);}).setNegativeButton("Закрыть",null).setNeutralButton("Обновить",(d,w)->browseSmb(url,login,password,parents));if(!parents.isEmpty())dialog.setPositiveButton("Назад",(d,w)->{ArrayList<String> next=new ArrayList<>(parents);String previous=next.remove(next.size()-1);browseSmb(previous,login,password,next);});dialog.show();});}catch(Exception e){runOnUiThread(()->{if(isDestroyed()||generation!=smbBrowseGeneration)return;progress.dismiss();status.setText("Ошибка доступа к SMB");new AlertDialog.Builder(this).setTitle("Сетевая папка недоступна").setMessage("Проверьте адрес, права доступа и подключение к сети.").setPositiveButton("Повторить",(d,w)->browseSmb(url,login,password,parents)).setNegativeButton("Закрыть",null).show();});}},"SmbBrowser").start();}
 void playSmb(String url,String login,String password){closeShift();current=null;usingBackup=false;applyAudioTrim();retryHandler.removeCallbacksAndMessages(null);androidx.media3.datasource.DataSource.Factory factory=()->new SmbDataSource(url,login,password);androidx.media3.exoplayer.source.ProgressiveMediaSource source=new androidx.media3.exoplayer.source.ProgressiveMediaSource.Factory(factory).createMediaSource(new MediaItem.Builder().setUri("smb://vision.local/video").setMediaId("vision-smb").build());player.setMediaSource(source);player.prepare();player.play();status.setText("Видео SMB • потоковое воспроизведение");video.requestFocus();}
 LocalTimeshift localShift;
 boolean isLocalShift(){MediaItem item=player.getCurrentMediaItem();return item!=null&&"vision-shift".equals(item.mediaId);}
