 void startLocalShift(){if(current==null||isArchive()||localShift!=null){Toast.makeText(this,"Выберите прямой эфир",Toast.LENGTH_SHORT).show();return;}Channel ch=current;String address=activeLiveUrl(ch);long[] limits={128L,256L,512L,1024L};int size=Math.max(0,Math.min(3,prefs.getInt("shiftSize",1)));try{LocalTimeshift shift=new LocalTimeshift(getCacheDir(),limits[size]*1024*1024,prefs.getString("streamUserAgent","VisionIPTV/1.0"));localShift=shift;player.stop();status.setText("Timeshift: подготовка…");shift.start(address,new LocalTimeshift.Listener(){public void ready(String url){runOnUiThread(()->{if(localShift!=shift||current!=ch||isDestroyed())return;player.setMediaItem(new MediaItem.Builder().setUri(url).setMediaId("vision-shift").build());player.prepare();player.play();status.setText("Локальный Timeshift • "+ch.name);});}public void failed(String reason){runOnUiThread(()->{if(localShift!=shift||isDestroyed())return;returnLive();Toast.makeText(MainActivity.this,"Timeshift недоступен для этого потока",Toast.LENGTH_LONG).show();});}});}catch(Exception e){closeShift();Toast.makeText(this,"Не удалось создать локальный буфер",Toast.LENGTH_LONG).show();}}
